"""Test all API endpoints"""
import requests
import json

BASE = "http://127.0.0.1:8000"

def test(name, method, url, data=None):
    print(f"\n{'='*60}")
    print(f"  {name}")
    print(f"  {method} {url}")
    print(f"{'='*60}")
    try:
        if method == "GET":
            r = requests.get(url, timeout=30)
        else:
            r = requests.post(url, json=data, timeout=60)
        print(f"Status: {r.status_code}")
        print(f"Response:\n{json.dumps(r.json(), indent=2)}")
    except Exception as e:
        print(f"ERROR: {e}")

# 1. Health check
test("Health Check", "GET", f"{BASE}/health")

# 2. Predict structure (short insulin fragment)
test("Predict Structure", "POST", f"{BASE}/predict", {
    "sequence": "MALWMRLLPLLALLALWGPDPAAAFVNQHLCGSHLVEALYLVCGERGFFYTPKT"
})

# 3. Analyze mutation (BRCA1 example)
test("Analyze Mutation", "POST", f"{BASE}/analyze", {
    "sequence": "",
    "mutation": "C61G",
    "gene_name": "BRCA1"
})

# 4. Compare (perplexity comparison)
test("Compare Perplexity", "POST", f"{BASE}/compare", {
    "sequence": "MALWMRLLPLLALLALWGPDPAAAFVNQHLCGSHLVEALYLVCGERGFFYTPKT"
})

print("\n" + "="*60)
print("  ALL TESTS COMPLETE")
print("="*60)
